import subprocess
import os
import glob
import time
def task_func(test_dir):
    times = {}
    for script in glob.glob(os.path.join(test_dir, '*.py')):
        start = time.time()
        subprocess.run(['python', script], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        end = time.time()
        times[os.path.basename(script)] = end - start
    return times

